<script setup lang="ts">
import { apiPath } from '@/utils/api'
import type { Category,GisLocation } from '@/types/gis';definePageMeta({middleware:'admin',layout:'admin'});const route=useRoute();const id=Number(route.params.id);const [{data:item},{data:cats}]=await Promise.all([useFetch<GisLocation>(apiPath(`/api/admin/locations/${id}`)),useFetch<{items:Category[]}>(apiPath('/api/admin/categories'),{default:()=>({items:[]})})]);const saving=ref(false);async function save(body:Record<string,unknown>){saving.value=true;try{await $fetch(apiPath(`/api/admin/locations/${id}`),{method:'PUT',body});item.value=await $fetch(apiPath(`/api/admin/locations/${id}`))}finally{saving.value=false}}</script><template><div class="space-y-5"><div><h1 class="text-2xl font-bold tracking-tight">Edit Location</h1><p class="mt-1 text-sm text-muted-foreground">ID #{{id}}</p></div><LocationForm v-if="item" :key="item.updated_at" :categories="cats.items" :initial="item" :submit-label="saving?'Menyimpan...':'Simpan perubahan'" @submit="save" /></div></template>
